package com.example.grafanapocket;

import android.app.*;import android.content.*;import android.graphics.Color;import android.net.Uri;import android.os.*;import android.view.*;import android.webkit.*;import android.widget.*;import java.util.*;

public class DashboardActivity extends Activity {
    Connection connection;LinearLayout content;TextView status;final List<WebView> views=new ArrayList<>();Handler handler=new Handler(Looper.getMainLooper());Runnable reload;
    @Override public void onCreate(Bundle b){super.onCreate(b);buildShell();startSession();}
    void buildShell(){connection=new SecureStore(this).get(getIntent().getStringExtra("id"));if(connection==null){finish();return;}LinearLayout root=new LinearLayout(this);root.setOrientation(LinearLayout.VERTICAL);root.setBackgroundColor(Ui.BG);Ui.applySystemBars(root);LinearLayout bar=new LinearLayout(this);TextView title=Ui.title(this,connection.name);title.setTextSize(17);bar.addView(title,new LinearLayout.LayoutParams(0,-2,1));Button choose=Ui.button(this,"选择窗口");choose.setOnClickListener(v->startActivityForResult(new Intent(this,PanelSelectionActivity.class).putExtra("id",connection.id),9));bar.addView(choose);Button refresh=Ui.button(this,"刷新");refresh.setOnClickListener(v->reloadAll());bar.addView(refresh);root.addView(bar);status=Ui.title(this,"正在登录…");status.setTextSize(14);root.addView(status);ScrollView scroll=new ScrollView(this);content=new LinearLayout(this);content.setOrientation(LinearLayout.VERTICAL);scroll.addView(content);root.addView(scroll,new LinearLayout.LayoutParams(-1,0,1));setContentView(root);}
    void startSession(){new Thread(()->{try{GrafanaApi.ensureLogin(connection);runOnUiThread(()->{status.setVisibility(View.GONE);showPanels();});}catch(Exception e){runOnUiThread(()->status.setText(e.getMessage()+"。请长按首页连接检查账号密码。"));}}).start();}
    void showPanels(){for(WebView w:views)w.destroy();views.clear();content.removeAllViews();connection=new SecureStore(this).get(connection.id);String override=getIntent().getStringExtra("path");String base=override==null?connection.dashboard:override;if(connection.panels==null||connection.panels.isEmpty()||override!=null){addWeb(base,-1);}else for(String id:connection.panels.split(","))try{addWeb(base,Integer.parseInt(id));}catch(Exception ignored){}if(connection.refreshSeconds>0){handler.removeCallbacksAndMessages(null);reload=()->{reloadAll();handler.postDelayed(reload,connection.refreshSeconds*1000L);};handler.postDelayed(reload,connection.refreshSeconds*1000L);}}
    void addWeb(String path,int panelId){if(panelId>=0){TextView label=Ui.title(this,"Panel #"+panelId);label.setTextSize(14);content.addView(label);path=solo(path,panelId);}WebView web=new WebView(this);configure(web);int height=panelId>=0?(int)(320*getResources().getDisplayMetrics().density):getResources().getDisplayMetrics().heightPixels;content.addView(web,new LinearLayout.LayoutParams(-1,height));views.add(web);load(web,path);}
    String solo(String path,int panelId){String[] q=path.split("\\?",2);String p=q[0];if(p.startsWith("/d/"))p="/d-solo/"+p.substring(3);String query=q.length>1?q[1]+"&":"";return p+"?"+query+"panelId="+panelId+"&kiosk";}
    void configure(WebView web){WebSettings s=web.getSettings();s.setJavaScriptEnabled(true);s.setDomStorageEnabled(true);s.setDatabaseEnabled(true);s.setMixedContentMode(WebSettings.MIXED_CONTENT_ALWAYS_ALLOW);s.setBuiltInZoomControls(true);s.setDisplayZoomControls(false);s.setUserAgentString(s.getUserAgentString()+" GrafanaPocket/1.1");web.setWebViewClient(new WebViewClient(){@Override public void onReceivedHttpAuthRequest(WebView v,HttpAuthHandler h,String host,String realm){if("basic".equals(connection.auth))h.proceed(connection.user,connection.secret);else h.cancel();}@Override public boolean shouldOverrideUrlLoading(WebView v,WebResourceRequest r){Uri u=r.getUrl();Uri base=Uri.parse(connection.url);if(base.getHost()!=null&&base.getHost().equalsIgnoreCase(u.getHost()))return false;startActivity(new Intent(Intent.ACTION_VIEW,u));return true;}});}
    void load(WebView web,String path){String target=connection.url+(path.startsWith("/")?path:"/"+path);Map<String,String> headers=new HashMap<>();if("token".equals(connection.auth)&&!connection.secret.isEmpty())headers.put("Authorization","Bearer "+connection.secret);web.loadUrl(target,headers);}
    void reloadAll(){for(WebView w:views)w.reload();}
    @Override protected void onActivityResult(int request,int result,Intent data){super.onActivityResult(request,result,data);if(request==9&&result==RESULT_OK)showPanels();}
    @Override public void onBackPressed(){if(views.size()==1&&views.get(0).canGoBack())views.get(0).goBack();else super.onBackPressed();}
    @Override protected void onDestroy(){handler.removeCallbacksAndMessages(null);for(WebView w:views){w.stopLoading();w.destroy();}super.onDestroy();}
}
